def tournament(F, k, rng):
    # k учасників навмання з поверненням (одна особина може потрапити в турнір двічі)
    idx = rng.integers(0, len(F), size=k)
    # переможець - найкоротший маршрут серед учасників; повертаю його номер у популяції, а не довжину
    return int(idx[np.argmin(F[idx])])
